import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from './db'

// Shared catalog accessor: every view that renders catalog data should read
// through this function so the 'products' tag invalidates them all at once.
export async function getProducts() {
  'use cache'
  cacheTag('products')
  // The catalog only changes when an admin triggers a sync, so cache
  // indefinitely and rely on on-demand invalidation via the tag.
  cacheLife('max')

  return getAllProducts()
}

