import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function Page() {
  async function syncCatalog() {
    'use server'

    // Kick off the upstream ERP/PIM sync, then mark the catalog stale with
    // the 'max' profile: readers keep getting the cached catalog instantly
    // while fresh data is recomputed in the background, instead of blocking
    // on a full re-query of thousands of SKUs.
    revalidateTag('products', 'max')
  }

  const products = await getProducts()

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

